class GateQuery { private isCount=false; private result:any; readonly filters:string[]; constructor(result:any,filters:string[]=[]){this.result=result;this.filters=filters} select(_fields?:string,_options?:{count?:string}){this.isCount=Boolean(_options?.count);return this} eq(column:string,value:unknown){this.filters.push(`eq:${column}=${String(value)}`);return this} neq(column:string,value:unknown){this.filters.push(`neq:${column}=${String(value)}`);return this} in(column:string,values:unknown[]){this.filters.push(`in:${column}=${values.join(",")}`);return this} order(){return this} limit(){return this} maybeSingle(){return Promise.resolve(this.result.single ?? {data:null,error:null})} then(resolve:any,reject:any){const value=this.isCount?(this.result.count ?? {count:null,error:null}):(this.result.data ?? {data:null,error:null});return Promise.resolve(value).then(resolve,reject)} }
function gateDb(results:Record<string,any>){return{from(table:string){const result=results[table]||{};const query=new GateQuery(result);if(table==="commerce_repository_activation") (results as any).__activationQuery=query;return query}}}
