function safeGateResults(activationCount:number|undefined=0){return{"commerce_provider_connections":{single:{data:{provider:"commas",status:"connected",account_id:gateMessage.account_id},error:null}},"commerce_provider_accounts":{data:{data:[{id:gateMessage.provider_account_id}],error:null}},"tracekit_production_controls":{count:{count:0,error:null}},"commerce_sync_schedules":{count:{count:0,error:null}},"commerce_sync_runs":{count:{count:0,error:null},single:{data:{metadata:{}},error:null}},"commerce_repository_activation":{count:{count:activationCount,error:null}}}}
