test("bootstrap consumer is allowed with normal controls disabled and reserves once",async()=>{let reservations=0,runs=0;const bootstrapMessage={...message,bootstrap:true as const,bootstrap_mode:"quota-bootstrap" as const};const repository=repo({schedulerEnabled:async()=>false,bootstrapPermitted:async()=>true,reserve:async()=>{reservations++;return reservations===1?"reserved":"duplicate"}});const runtime={run:async()=>{runs++;return{status:"completed" as const,providerRequests:1}}};const first=await consumeCommerceMessage({value:bootstrapMessage,repository:{...repository},runtime});const second=await consumeCommerceMessage({value:bootstrapMessage,repository:{...repository},runtime});assert.equal(first.status,"completed");assert.equal(second.status,"duplicate");assert.equal(runs,1)});
test("producer-reserved bootstrap skips the second reservation and dispatches once",async()=>{let reservations=0,runs=0;const bootstrapMessage={...message,bootstrap:true as const,bootstrap_mode:"quota-bootstrap" as const,reserved_run_id:id};const repository=repo({schedulerEnabled:async()=>false,bootstrapPermitted:async()=>true,preReservedRunPermitted:async()=>true,reserve:async()=>{reservations++;return"duplicate" as const}});const result=await consumeCommerceMessage({value:bootstrapMessage,repository,runtime:{run:async()=>{runs++;return{status:"completed" as const,providerRequests:1}}}});assert.equal(result.status,"completed");assert.equal(reservations,0);assert.equal(runs,1)});
test("operator one-shot uses the pre-reserved queue path while scheduler remains disabled",async()=>{let reservations=0,runs=0;const oneShot={...message,operator_one_shot:true as const,acceptance_cycle:true as const,max_pages:8,per_page:100,request_key:id,reserved_run_id:id};const result=await consumeCommerceMessage({value:oneShot,repository:repo({schedulerEnabled:async()=>false,operatorOneShotPermitted:async()=>true,preReservedRunPermitted:async()=>true,reserve:async()=>{reservations++;return"duplicate" as const}}),runtime:{run:async()=>{runs++;return{status:"completed" as const,providerRequests:8}}}});assert.equal(result.status,"completed");assert.equal(reservations,0);assert.equal(runs,1)});
test("operator gate excludes only its validated reservation and keeps post-reservation diagnostics distinct",()=>{
  const source=readFileSync(new URL("./index.ts",import.meta.url),"utf8");
  const start=source.indexOf("async operatorOneShotPermitted(message)");
  const end=source.indexOf("async reserve(message)",start);
  const gate=source.slice(start,end);
  assert.match(gate,/preReservedRunPermitted!\(message\)/);
  assert.match(gate,/\.neq\("id", message\.reserved_run_id\)/);
  assert.match(gate,/\(activeRuns \|\| \[\]\)\.length === 0/);
  assert.match(gate,/metadata \|\| \{\}\).*account_id|metadata \|\| \{\}\)\.account_id|\.account_id \|\| ""\) === message\.account_id/);
  const route=source.slice(source.indexOf('path === "/internal/commerce/one-shot-shadow"'),source.indexOf('path === "/v1/commerce/sync-now"'));
  assert.match(route,/reservation_rejected/);
  assert.match(route,/post_reservation_validation_rejected/);
  assert.match(route,/post_reservation_gate_rejected/);
});
test("invalid pre-reserved bootstrap references fail closed while ordinary duplicates remain suppressed",async()=>{const bootstrapMessage={...message,bootstrap:true as const,bootstrap_mode:"quota-bootstrap" as const,reserved_run_id:id};let runs=0;const invalid=await consumeCommerceMessage({value:bootstrapMessage,repository:repo({schedulerEnabled:async()=>false,bootstrapPermitted:async()=>true,preReservedRunPermitted:async()=>false}),runtime:{run:async()=>{runs++;return{status:"completed" as const,providerRequests:1}}}});assert.equal(invalid.status,"invalid_reserved_run");assert.equal(runs,0);const ordinary=await consumeCommerceMessage({value:message,repository:repo({reserve:async()=>"duplicate" as const}),runtime:{run:async()=>{runs++;return{status:"completed" as const,providerRequests:1}}}});assert.equal(ordinary.status,"duplicate");assert.equal(runs,0)});
test("manual delivery uses its own guarded permission while scheduler is disabled",async()=>{let runs=0;const manualMessage={...message,manual:true as const};const result=await consumeCommerceMessage({value:manualMessage,repository:repo({schedulerEnabled:async()=>false,manualPermitted:async()=>true}),runtime:{run:async()=>{runs++;return{status:"completed" as const,providerRequests:1}}}});assert.equal(result.status,"completed");assert.equal(runs,1);assert.throws(()=>validateCommerceQueueMessage({...manualMessage,bootstrap:true,bootstrap_mode:"quota-bootstrap"}),/invalid_queue_message/)})
test("cron enqueues bounded continuous and deep messages",async()=>{const sent:any[]=[];const repository=repo({eligibleJobs:async()=>[{accountId:id,organizationId,connectionId:id,providerAccountId,resource:"transactions",mode:"continuous",schedulerIdentity:"overlap",quotaRemaining:9000,requestBudget:8,quotaFloor:1000},{accountId:id,organizationId,connectionId:id,providerAccountId,resource:"transactions",mode:"deep_reconciliation",schedulerIdentity:"deep",quotaRemaining:9000,requestBudget:800,quotaFloor:2000}]});assert.equal((await runCommerceCron({now:message.requested_at,repository,queue:{send:async value=>{sent.push(value)}}})).enqueued,2);assert.deepEqual(sent.map(x=>x.requested_mode),["continuous","deep_reconciliation"])});
test("duplicate reservation suppresses at-least-once enqueue",async()=>{let sent=0;const result=await runCommerceCron({now:message.requested_at,repository:repo({reserve:async()=>"duplicate"}),queue:{send:async()=>{sent++}}});assert.equal(result.duplicates,1);assert.equal(sent,0)});
test("consumer rechecks kill switch and Connection pause",async()=>{let runs=0;const result=await consumeCommerceMessage({value:message,repository:repo({connectionPermitted:async()=>false}),runtime:{run:async()=>{runs++;return{status:"completed",providerRequests:2}}}});assert.equal(runs,0);assert.equal(result.status,"disabled")});
test("consumer invokes existing runtime once and duplicate delivery converges through runtime identity",async()=>{let runs=0;const runtime={run:async()=>{runs++;return{status:"completed" as const,providerRequests:2}}};await consumeCommerceMessage({value:message,repository:repo(),runtime});await consumeCommerceMessage({value:message,repository:repo(),runtime});assert.equal(runs,2);assert.equal(message.scheduler_identity,"schedule:bucket")});
test("consumer classifies retryable and permanent failures",async()=>{for(const [error,retry]of[[new Error("provider 429"),true],[Object.assign(new Error("schema drift"),{code:"schema_drift"}),false],[new Error("credential invalid"),false],[new Error("lease conflict"),true]]as const){const result=await consumeCommerceMessage({value:message,repository:repo(),runtime:{run:async()=>{throw error}}});assert.equal(result.retry,retry)}});
